"""Markdown tables for the exploratory T5 API-LLM cells -> results/api/api_tables.md. LLM group only (T3 local + T5 API)."""
import json, os, sys, glob
import numpy as np, datetime
IST = lambda t: (datetime.datetime.strptime(t, "%Y-%m-%dT%H:%M:%SZ") + datetime.timedelta(hours=3)).strftime("%H:%M") if t else "?"   # Europe/Istanbul, UTC+3
sys.path.insert(0, os.path.dirname(__file__)); from core import ROOT, DATASETS, RAW
R = f"{ROOT}/results"; out = []; P = out.append
DSN = {"agnews": "AG News", "bbc2025": "BBC 2024-25", "sst2": "SST-2", "dbpedia": "DBpedia-14", "massive": "MASSIVE-18"}
f3 = lambda x: "–" if x is None or (isinstance(x, float) and not np.isfinite(x)) else f"{x:.3f}"; f2 = lambda x: "–" if x is None or (isinstance(x, float) and not np.isfinite(x)) else f"{x:.2f}"
ci = lambda c, f=f3: f"[{f(c[0])}, {f(c[1])}]" if c else ""
cells = {os.path.basename(f)[:-5]: json.load(open(f)) for f in sorted(glob.glob(f"{R}/cells/*.json")) if os.path.basename(f)[:-5].count("__") == 2}
llm = {k: v for k, v in cells.items() if v["kind"] in ("llm", "api") and not any(t in k for t in ("_tau", "_rawll", "_sub"))}
keys = sorted(llm, key=lambda k: (DATASETS.index(llm[k]["dataset"]), llm[k]["kind"], llm[k]["model"]))
T = lambda v: "T5 API" if v["kind"] == "api" else "T3 local"
P("# Exploratory API-LLM tables (generated by src/api_tables.py)\n")
P("Generative LLMs are compared only with other LLMs (T3 local small LLMs, T5 closed API LLMs). T5 cells are not preregistered (deviation: they replace local LLM cells that were infeasible on CPU).\n")
P("## A1. Cells, cost and data quality\n"); P("| type | dataset | model | items | wording sets scored | refusals (item×set) | missing letters | USD | API window (Istanbul, UTC+3, 2026-10-17) | model id returned |"); P("|---|---|---|---|---|---|---|---|---|---|")
tot = 0.0
for k in keys:
    v = llm[k]; m = v["meta"]
    if v["kind"] == "api":
        tot += m["usd"]; P(f"| {T(v)} | {DSN[v['dataset']]} | {v['model']} | {v['N']} | {m['n_sets']} | {m['refusals']} | {f3(m.get('missing_letter_rate'))} | {m['usd']:.2f} | {IST(m['first_request_utc'])}–{IST(m['last_request_utc'])} | {', '.join(m['model_ids_returned'])} |")
    else: P(f"| {T(v)} | {DSN[v['dataset']]} | {v['model']} | {v['N']} | – | – | – | – | local CPU | {m.get('model')} |")
P(f"\nSum of main-cell API cost: ${tot:.2f}.\n")
led = {}
for f in glob.glob(f"{ROOT}/logs/api/spend/*.json"):
    m_, ds_, c_ = os.path.basename(f)[:-5].split("__"); g = "main" if c_ == "main" else ("option order" if c_.startswith("ord") else ("retest" if c_.startswith("rt") else ("pilot" if c_.startswith("pilot") else "smoke test")))
    led[(m_, g)] = led.get((m_, g), 0.0) + json.load(open(f))["usd"]
P("Total spend from the usage fields (ledger logs/api/spend/*.json; list prices, cached-token discounts ignored, so an upper bound): " + "; ".join(f"{m_} {g} ${v:.2f}" for (m_, g), v in sorted(led.items())) + f"; **total ${sum(led.values()):.2f}** of the $23 cap (API_CAP_USD in src/score_api.py). A handful of manual probe requests before the scorer existed are not in the ledger (< $0.001).\n")
P("## A2. Accuracy and RQ1 budget at n = 250 (LAC, α = 0.10)\n"); P("| type | dataset | model | acc official | acc VALID mean [min, max] | mean set size | σ_wording [CI] | σ_split | ratio [CI] | wording share [CI] |"); P("|---|---|---|---|---|---|---|---|---|---|")
for k in keys:
    v = llm[k]; n = 250 if 250 in v["n_grid"] else v["n_grid"][0]; b = v["floor"][f"A|lac|valid|{n}"]["set_size"]; a = [v["point"][s]["accuracy"] for s in v["point"] if s.startswith("valid_")]
    P(f"| {T(v)} | {DSN[v['dataset']]} | {v['model']} | {f3(v['point']['official']['accuracy'])} | {f3(np.mean(a))} [{f3(min(a))}, {f3(max(a))}] | {f3(b['mean'])} | {f3(b['sd_w'])} {ci(b['ci_sd_w'])} | {f3(b['sd_s'])} | {f2(b['ratio_w_s'])} {ci(b['ci_ratio_w_s'], f2)} | {f2(b['share_w'])} {ci(b['ci_share_w'], f2)} |")
P("\n## A3. APS at n = 250 and n_max, and wording slope (floor)\n"); P("| type | dataset | model | APS share_w n=250 | LAC σ_w n_max [CI] | LAC σ_s n_max | n_max | wording slope n≥250 | split slope n≥100 |"); P("|---|---|---|---|---|---|---|---|---|")
SA = json.load(open(f"{R}/summary_api.json")) if os.path.exists(f"{R}/summary_api.json") else {}
SW = json.load(open(f"{R}/summary_with_api.json")) if os.path.exists(f"{R}/summary_with_api.json") else {}
r2 = {x["cell"]: x for x in SW.get("verdicts", {}).get("RQ2", {}).get("cells", [])}
for k in keys:
    v = llm[k]; n = 250 if 250 in v["n_grid"] else v["n_grid"][0]; nm = v["n_grid"][-1]; ap = v["floor"][f"A|aps|valid|{n}"]["set_size"]; bm = v["floor"][f"A|lac|valid|{nm}"]["set_size"]; x = r2.get(k, {})
    P(f"| {T(v)} | {DSN[v['dataset']]} | {v['model']} | {f2(ap['share_w'])} {ci(ap['ci_share_w'], f2)} | {f3(bm['sd_w'])} {ci(bm['ci_sd_w'])} | {f3(bm['sd_s'])} | {nm} | {f2(x.get('slope_sd_w_n250'))} | {f2(x.get('slope_sd_split_n100'))} |")
P("\n## A4. Surface (case-only) control, configuration shift, controls\n"); P("| type | dataset | model | surface flip mean | VALID flip mean | surface/valid | config-shift coverage mean [min] | share of sets < 0.85 | nonsense acc | shuffled acc | identity flip |"); P("|---|---|---|---|---|---|---|---|---|---|---|")
for k in keys:
    v = llm[k]; fl = v["flip_vs_official"]; s = [fl[x] for x in fl if x.startswith("surface_")]; va = [fl[x] for x in fl if x.startswith("valid_")]; cs = [x["coverage_mean"] for x in v["config_shift_official_to_valid"]]
    na = [v["point"][x]["accuracy"] for x in v["point"] if x.startswith("N")]; sh = [v["point"][x]["accuracy"] for x in v["point"] if x.startswith("shuffled")]
    P(f"| {T(v)} | {DSN[v['dataset']]} | {v['model']} | {f3(np.mean(s)) if s else '–'} | {f3(np.mean(va))} | {f2(np.mean(s) / np.mean(va)) if s and np.mean(va) > 0 else '–'} | {f3(np.mean(cs))} [{f3(min(cs))}] | {f2(np.mean(np.array(cs) < 0.85))} | {f3(np.mean(na)) if na else '–'} | {f3(np.mean(sh)) if sh else '–'} | {f3(fl.get('identity', np.nan))} |")
p = f"{R}/api/option_order.json"
if os.path.exists(p):
    O = json.load(open(p)); P("\n## A5. Exploratory option-order factor (600 items, 30 VALID sets × 3 orders × 200 splits, n = 250, α = 0.10)\n")
    P("| dataset | model | metric | mean | σ_wording [CI] | σ_order [CI] | σ_split [CI] | share wording [CI] | share order [CI] | σ_order/σ_wording | flips between orders | flips vs official wording | TV between orders | TV vs official wording | mean p by display position (perm. orders) |"); P("|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|")
    for k, r in O.items():
        ds, m = k.split("__"); it = r["item_level"]
        for met in ("lac_set_size", "aps_set_size"):
            b = r[met]; P(f"| {DSN[ds]} | {m} | {met.replace('_set_size', '').upper()} size | {f3(b['mean'])} | {f3(b['sd']['w'])} {ci(b['ci_sd_w'])} | {f3(b['sd']['o'])} {ci(b['ci_sd_o'])} | {f3(b['sd']['s'])} {ci(b['ci_sd_s'])} | {f2(b['share']['w'])} {ci(b['ci_share_w'], f2)} | {f2(b['share']['o'])} {ci(b['ci_share_o'], f2)} | {f2(b['ratio_sd_o_over_sd_w'])} | {f3(it['argmax_flip_between_orders_mean'])} | {f3(it['argmax_flip_vs_official_wording_mean'])} | {f3(it['tv_between_orders_mean'])} | {f3(it['tv_vs_official_wording_mean'])} | {', '.join(f2(x) for x in it['mean_prob_by_display_position_perm_orders'])} |")
    P("\nAccuracy by order (canonical, perm1, perm2), mean over 30 VALID sets: " + "; ".join(f"{DSN[k.split('__')[0]]} {k.split('__')[1]}: " + ", ".join(f3(x) for x in r["item_level"]["accuracy_mean_by_order"]) + f" (SD over wordings {f3(r['item_level']['accuracy_sd_over_wordings'])}, mean SD over orders within wording {f3(r['item_level']['accuracy_sd_over_orders_within_wording_mean'])})" for k, r in O.items()))
p = f"{R}/repeatability.json"
if os.path.exists(p):
    Rp = json.load(open(p)); ks = [k for k in ("api-luna", "api-nano") if k in Rp]
    if ks:
        P("\n## A6. API test-retest (AG News items 0–199, official + 30 VALID sets, main run + 2 reruns)\n"); P("| instrument | runs | request windows (Istanbul, UTC+3) | max \\|Δp\\| (max over sets) | mean \\|Δp\\| | share of items with any Δp > 0 (mean over sets) | share items same argmax in all runs (min over sets) | Fleiss κ (min) | ICC(2,1) on p(true) (min) | share of test items whose LAC set changes (mean / max) | system fingerprints |"); P("|---|---|---|---|---|---|---|---|---|---|---|")
        for k in ks:
            s = Rp[k]["summary"]; w = "; ".join(f"{IST(a)}–{IST(b)}" for a, b in Rp[k]["request_windows_utc"])
            P(f"| {k} | {Rp[k]['runs']} | {w} | {s['max_abs_dp']['max']:.3g} | {s['mean_abs_dp']['mean']:.3g} | {f3(s['share_items_any_dp_gt_0']['mean'])} | {f3(s['share_items_same_label_all_runs']['min'])} | {f3(s['fleiss_kappa']['min'])} | {f3(s['icc21']['min'])} | {f3(s['share_test_sets_changed']['mean'])} / {f3(s['share_test_sets_changed']['max'])} | {', '.join(sorted({x for f in Rp[k]['system_fingerprints'] for x in (f or [])})) or '–'} |")
p = f"{R}/api/luna_pilot.json"
if os.path.exists(p):
    L = json.load(open(p)); P("\n## A7. Luna pilot: questions per Decisions request (100 AG News items × 31 sets)\n"); P("| comparison | (item,set) pairs | max \\|Δp\\| | argmax flip rate |"); P("|---|---|---|---|")
    for k, r in L["pairs"].items(): P(f"| {k.replace('pilot_', '')} | {r['n_pairs']} | {r['max_abs_dp']:.3g} | {f3(r['argmax_flip_rate'])} |")
    q = L["quantisation"]; P(f"\nQuantisation: {100*q['share_on_0.01_grid']:.1f}% of {q['n_values']} returned probabilities lie on the 0.01 grid; {q['distinct_values']} distinct values; {100*q['share_exact_0']:.1f}% exactly 0 and {100*q['share_exact_1']:.1f}% exactly 1; every answer sums to 1 (max deviation {q['sum_to_1_abs_dev_max']:.1e}). Refusals per run: {L['refusals']['pilot_q1']} of 3,100.")
for sec, nm, S_ in [("A8", "prereg + API (T1–T3 + T5)", SW), ("A9", "API only (T5)", SA)]:
    V = S_.get("verdicts", {})
    if not V: continue
    P(f"\n## {sec}. Preregistered criteria re-evaluated on {nm} ({S_.get('n_cells_zero_shot')} cells; exploratory)\n")
    r1 = V.get("RQ1", {}); r2_ = V.get("RQ2", {}); r3 = V.get("RQ3", {})
    P(f"- RQ1: H1a {r1.get('H1a')} (share {f2(r1.get('share_cells_sd_w_ci_excludes_0_and_holm_sig'))}); H1b {r1.get('H1b')} (in range {f2(r1.get('share_cells_ratio_in_[1/3,3]'))}, >3 {f2(r1.get('share_cells_ratio_gt_3'))}, <1/3 {f2(r1.get('share_cells_ratio_lt_1/3'))})")
    P(f"- RQ2: H2a {r2_.get('H2a')} ({f2(r2_.get('share_H2a_split_slope_in_range'))}); H2b {r2_.get('H2b')} ({f2(r2_.get('share_H2b_flat_wording_floor'))}); H2c {r2_.get('H2c')} ({f2(r2_.get('share_H2c_W4_estimate_within_0.8_1.25'))})")
    P(f"- RQ3: H3a by type {r3.get('H3a_by_type')}; share of cells surface ≥ 0.5 valid: {f2(r3.get('share_cells_surface_ge_half_valid'))}; H3c {r3.get('H3c')} ({f2(r3.get('share_H3c_valid_lt_all'))}); dose-response {r3.get('H3b')}")
open(f"{R}/api/api_tables.md", "w").write("\n".join(out) + "\n"); print("\n".join(out)[:3000])
